    "description": "宁德时代7月24日的业绩说明会上，关于“公司推出大额回购方案的原因？是不是会常态化？”的问题，宁德时代称，近期资本市场有一定波动，公司股价也有所下跌，综合考虑公司财务状况、行业地位、资本市场等因素，且为应对未来可能因市场波动而出现公司股价大幅下滑、估值与公司实际价值不匹配的情况，公司推出了回购计划，本质上是对公司长期发展前景充满信心。回购事项需要综合考虑诸多因素，公司将根据具体情况一事一议、逐项进行审慎分析及合规审议。（证券时报）",
    "content": "宁德时代7月24日的业绩说明会上，关于“公司推出大额回购方案的原因？是不是会常态化？”的问题，宁德时代称，近期资本市场有一定波动，公司股价也有所下跌，综合考虑公司财务状况、行业地位、资本市场等因素，且为应对未来可能因市场波动而出现公司股价大幅下滑、估值与公司实际价值不匹配的情况，公司推出了回购计划，本质上是对公司长期发展前景充满信心。回购事项需要综合考虑诸多因素，公司将根据具体情况一事一议、逐项进行审慎分析及合规审议。（证券时报）"
