    "description": "中新网7月27日电 据“中国海警”微信公众号消息，7月25日19时37分，中国海警接海南省海上搜救中心通报，1艘越南籍船舶在永暑礁以北38海里附近海域遇险沉没。接到通报后，中国海警立即派遣两艘海警舰赶赴事发海域展开搜救。7月26日晚，中国海警宣德舰、南沙舰在持续开展搜救过程中，宣德舰先后发现两名落水越南籍遇险船员，海警执法员迅速开展施救，分别于22时38分、23时32分成功将两人安全救起，两名获救人员生命体征正常。",
    "content": "中新网7月27日电 据“中国海警”微信公众号消息，7月25日19时37分，中国海警接海南省海上搜救中心通报，1艘越南籍船舶在永暑礁以北38海里附近海域遇险沉没。接到通报后，中国海警立即派遣两艘海警舰赶赴事发海域展开搜救。7月26日晚，中国海警宣德舰、南沙舰在持续开展搜救过程中，宣德舰先后发现两名落水越南籍遇险船员，海警执法员迅速开展施救，分别于22时38分、23时32分成功将两人安全救起，两名获救人员生命体征正常。"
