    "content": "这两天，“艺人李权哲乘高铁占座事件”在网上引发热议，该艺人参加的活动主办方曾发布声明，试图将此事的责任归咎于“第三方票务预订环节的意外状况”。7月26日，铁路部门在回应此事时明确表示，该演艺人员乘坐的高铁车次车票出票后，“全程座位无变更”。 到底是怎么回事，相信公众已经看得很清楚了。其实，之前就有很多网友质疑活动主办方的说法，表示“没听说过高铁列车出票后还会调整座位”的情况。现在铁路部门在调查后给出的结论，也是狠狠打了艺人方面的脸。 按说，这本身也不是什么大事。在高铁列车上坐错了位置，不管是什么原因，打声招呼，及时…"
