    "author": "",
    "description": "近日获悉，首批北交所三个月持有期主题基金自7月24日起将陆续向中国证监会递交产品注册申请，目前已经确定华夏基金、易方达基金、汇添富基金、南方基金、嘉实基金、东财基金、富国基金及中信建投基金等8家管理人。这意味着公募产品布局北交所实现进一步扩容，也将进一步丰富北交所投资产品，吸引增量资金进场，改善二级市场流动性，助力创新型中小企业估值修复。 （中证报）",
