    "content": "新华社贝鲁特7月26日电（记者申峰 曹昌浩）黎巴嫩政府军26日发表声明说，以色列持续违反现有协议安排，阻碍黎军在黎南部地区部署，并延缓边境村庄居民返乡进程。 声明说，以军在多个地区持续实施破坏活动，包括拆毁民宅、破坏供水设施、焚毁数百年树龄的橄榄树等。此外，以军还在泰卜尼特村和西扎乌塔尔等地向黎军部署区域附近开火，干扰黎军部署行动。 声明说，尽管受到以军干扰，黎军仍将在西扎乌塔尔执行任务，协助当地居民返乡并保障其安全，同时继续在夫龙镇和斯里法镇推进部署行动。 黎巴嫩安全部门消息人士和当地目击者21日向新华社记者证实…"
