    "content": "26/07/2026 - 17:41 据彭博社援引四位知情人士报导称，美国已要求墨西哥效仿美方针对中国钢铁和铝产品设立的关税壁垒，对来自北美以外地区的进口产品征收类似“232条款”的关税。 此举旨在维护美、墨、加三国生产的钢铁所享有的优惠待遇，同时针对中国建立统一的外部关税壁垒。尽管这对美国贸易官员而言是一项重大诉求，但据知情人士透露，在《美墨加协定》（USMCA）审查框架下就更广泛协议进行谈判之际，墨西哥对这一提议持开放态度。 知情人士补充道，可能征收的关税所涉及的具体税率和产品仍在讨论之中。其中一位知情人士表示…"
