    "content": "新华社巴黎7月26日电（记者张百慧）总部位于法国巴黎的联合国教科文组织26日宣布，世界遗产委员会决定通过紧急程序将3处“面临重大威胁”的遗产地同时列入《世界遗产名录》和《濒危世界遗产名录》。 上述决定是在韩国釜山举行的联合国教科文组织第48届世界遗产大会上作出的。通过紧急程序列入名录的3处遗产地项目分别是南苏丹的博马-巴丁吉洛迁徙景观、黎巴嫩的阿迈勒山区城堡群和巴勒斯坦的塞巴斯提亚。 联合国教科文组织表示，应申请而启动的“紧急程序”反映出当前武装冲突、气候变化等多重危机频发的局势对遗产造成严重影响，并使其面临重大威…"
