    "author": "",
    "description": "美国战争部一份最新名单将88家中国机构列为从事“问题活动”、可能危害美国国家安全和科研诚信的机构。除了具军工背景的高校，复旦大学和上海交通大学这两所顶尖综合性大学也入列。 受访学者分析，美国对华的去风险范围正扩大，未来更多从事高科技研究的高校也可能受影响，中美科技合作和高端人才交流将受冲击。 美国战争部星期四（7月23日）公布的“第1286条”名单，依据2019年《国防授权法案》设立，旨在识别对美国科研项目和国家安全构成风险的外国高校和…",
    "content": "美国战争部一份最新名单将88家中国机构列为从事“问题活动”、可能危害美国国家安全和科研诚信的机构。除了具军工背景的高校，复旦大学和上海交通大学这两所顶尖综合性大学也入列。 受访学者分析，美国对华的去风险范围正扩大，未来更多从事高科技研究的高校也可能受影响，中美科技合作和高端人才交流将受冲击。 美国战争部星期四（7月23日）公布的“第1286条”名单，依据2019年《国防授权法案》设立，旨在识别对美国科研项目和国家安全构成风险的外国高校和研究机构。这份名单经历数次更新，最新版本将130家外国高校和机构定性为从事“问题…"
