    "author": "胡拿云",
    "description": "新华社广州7月26日电（记者胡拿云）今年第12号台风“红霞”于26日3时50分前后在广东省惠州市惠东县平海镇登陆，登陆时中心附近最大风力14级（强台风级），登陆后强度逐渐减弱。记者从广东省三防办了解到，截至26日18时，广东累计转移人员896254人。 广东省气象台监测，26日14时，“红霞”减弱为热带风暴级，17时“红霞”的中心位于广东清远佛冈县境内，外围最大风力8级（20米/秒）。预计，“红霞”将以15公里左右的时速向偏北方向移动，…",
    "content": "新华社广州7月26日电（记者胡拿云）今年第12号台风“红霞”于26日3时50分前后在广东省惠州市惠东县平海镇登陆，登陆时中心附近最大风力14级（强台风级），登陆后强度逐渐减弱。记者从广东省三防办了解到，截至26日18时，广东累计转移人员896254人。 广东省气象台监测，26日14时，“红霞”减弱为热带风暴级，17时“红霞”的中心位于广东清远佛冈县境内，外围最大风力8级（20米/秒）。预计，“红霞”将以15公里左右的时速向偏北方向移动，强度逐渐减弱，将于27日凌晨前后离开广东进入湖南南部。预计27日，粤北部分地区有…"
