    "title": "[Claude Code] 写了一份 Claude Code 使用笔记，从踩坑到能用顺手",
    "link": "https://www.v2ex.com/t/1229970#reply4",
    "pub_date": "2026-07-26 23:23:22",
    "author": "june6868",
    "description": "用 Claude Code 一段时间后，把踩过的坑整理成一篇笔记，能输出才是真的学到了。 一些容易踩坑的点也都有讲到：上下文什么时候该 /compact 、什么时候该开新对话； MCP 配置的几个常用命令；权限系统四种模式实际怎么切换更顺手。 另外写了一小节给不写代码的人看，运营、内容岗其实也能用自然语言让它处理文件、整理资料。 东西放这了： https://www.yuque.com/juennn/tnmoif/lmdlencynbq…",
    "content": "用 Claude Code 一段时间后，把踩过的坑整理成一篇笔记，能输出才是真的学到了。 一些容易踩坑的点也都有讲到：上下文什么时候该 /compact 、什么时候该开新对话； MCP 配置的几个常用命令；权限系统四种模式实际怎么切换更顺手。 另外写了一小节给不写代码的人看，运营、内容岗其实也能用自然语言让它处理文件、整理资料。 东西放这了： https://www.yuque.com/juennn/tnmoif/lmdlencynbqvq9vt 欢迎指正，理解有误或者有更好做法都直说，希望一起交流！"
