    "pub_date": "2026-07-26 22:46:22",
    "author": "",
    "description": "昨天(25日)，一艘越南籍船舶在南海海域遇险沉没。总台记者从交通运输部获悉，目前中方救助力量已成功救起45人，越方救起1人，共计46人被救起，目前仍有16人失联。",
    "content": "昨天(25日)，一艘越南籍船舶在南海海域遇险沉没。总台记者从交通运输部获悉，目前中方救助力量已成功救起45人，越方救起1人，共计46人被救起，目前仍有16人失联。"
