    "description": "新华社北京7月26日电 题：乌克兰袭击伊朗商船，两国缘何对抗升级？ 新华社记者刘赞 马倩 乌克兰军方25日在里海袭击一艘伊朗商船，伊方对此强烈谴责并召见乌克兰驻伊朗临时代办。分析人士认为，乌方此举旨在阻止伊朗向俄罗斯提供无人机等军用物资，并以此向美国示好。这起袭击事件表明乌伊关系紧张升级，以及美伊战事和俄乌冲突进一步相互影响，但乌克兰与伊朗走向全面对抗的可能性不大。 伊朗商船遭袭 据伊朗媒体报道，乌克兰军方25日凌晨在里海水域袭击了一艘…",
    "content": "新华社北京7月26日电 题：乌克兰袭击伊朗商船，两国缘何对抗升级？ 新华社记者刘赞 马倩 乌克兰军方25日在里海袭击一艘伊朗商船，伊方对此强烈谴责并召见乌克兰驻伊朗临时代办。分析人士认为，乌方此举旨在阻止伊朗向俄罗斯提供无人机等军用物资，并以此向美国示好。这起袭击事件表明乌伊关系紧张升级，以及美伊战事和俄乌冲突进一步相互影响，但乌克兰与伊朗走向全面对抗的可能性不大。 伊朗商船遭袭 据伊朗媒体报道，乌克兰军方25日凌晨在里海水域袭击了一艘伊朗商船并导致爆炸，造成一名船员死亡，另有一人受伤。伊朗外交部对此强烈谴责，称袭…"
