    "description": "由国家移民管理局、国家中医药管理局联合开展的2026年度“送医送药下基层”巡诊活动5月20日正式启动。自2021年至今，这项暖心巡诊服务已连续开展六年。六年来，活动足迹遍及全国九个沿边省份，覆盖810余个移民管理基层点位，为4.7万名戍边民警、职工及边境驻地群众送去免费健康诊疗与暖心关怀。一次次跨越山海的奔赴，不仅守护了边境一线的身心健康，更在广袤边关，留下了无数温暖动人的瞬间。 作者：陶冶、彭应涛、王雨佳 新华社音视频部制作",
