    "content": "7月26日14时许，甘肃省定西市渭源县双石门景区受短时强降雨影响发生山洪，山洪导致双石门沟附近部分露营自驾游游客被困。截至26日18时，已有10人遇难、23人受伤。伤员已被送医救治，另有174人已被救出。 中新社报道称，灾害发生后，国家防汛抗旱总指挥部(国家防总)办公室、应急管理部持续调度指导应急处置工作，派出工作组赶赴现场指导处置。国家防总针对甘肃启动防汛四级应急响应。国家综合性消防救援队伍305人、68车正在现场救援。目前，救援处置工作仍在进行中。 图说：事故发生前，定西市、渭源县曾发布气象预警信息。 澎湃新闻…"
