    "content": "新华社常州7月26日电（记者王恒志）中国羽毛球公开赛26日在江苏常州落幕，郭新娃/陈芳卉和刘圣书/谭宁分别为中国队夺得混双和女双金牌，陈雨菲收获女单亚军。 威克多中国羽毛球公开赛26日进入决赛日，中国队已提前锁定混双冠亚军，并冲击女双、女单两项冠军。率先进行的混双决赛中，两对中国组合冯彦哲/黄东萍、郭新娃/陈芳卉鏖战87分钟，后者以25:23、20:22、21:15艰难获胜，终结了对“凤凰”组合的七连败。黄东萍赛后表示，对手细节做得更好，他们有点跟着对方的节奏走。陈芳卉则直言“凤凰”组合连续两站打了10场比赛，在体…"
