    "content": "新华社杭州7月26日电（记者林德韧、夏亮）2026年国际射联全项世界杯26日进行了男子50米步枪三姿和男子10米气手枪项目的决赛。中国选手张常鸿以363.0环的成绩打破男子50米步枪三姿项目决赛世界纪录并夺得冠军，布帅航获得男子10米气手枪项目冠军。 7月26日，张常鸿在比赛中。图片来自国际射联官网 男子50米步枪三姿比赛竞争激烈，中国队仅有张常鸿从资格赛中突出重围杀入决赛。决赛开始后，张常鸿状态稳定，与以“中立个人运动员”身份参赛的波塔波夫交替领先。进入淘汰赛阶段，波塔波夫的状态出现波动，最后4枪仅有1枪超过10…"
