    "author": "徐壮,袁慧晶",
    "description": "一座城，一千年，一件事。 一片瓷，一颗匠心，一项世界遗产。 2026年7月25日，“景德镇手工瓷业遗存”申遗成功。《世界遗产名录》“瓷”主题空白终于由瓷的原乡——中国填补。 负责评估世界文化遗产申报项目的国际古迹遗址理事会认为，“景德镇手工瓷业遗存”见证了一种大规模集约化生产模式的形成，“展示了中国制瓷技术和瓷器艺术的创新发展，并对世界陶瓷产业的发展产生了深刻影响”。 瓷声如磬，千年回响。瓷为什么选择了景德镇？世界遗产为何诞生在景德镇？…",
    "content": "一座城，一千年，一件事。 一片瓷，一颗匠心，一项世界遗产。 2026年7月25日，“景德镇手工瓷业遗存”申遗成功。《世界遗产名录》“瓷”主题空白终于由瓷的原乡——中国填补。 负责评估世界文化遗产申报项目的国际古迹遗址理事会认为，“景德镇手工瓷业遗存”见证了一种大规模集约化生产模式的形成，“展示了中国制瓷技术和瓷器艺术的创新发展，并对世界陶瓷产业的发展产生了深刻影响”。 瓷声如磬，千年回响。瓷为什么选择了景德镇？世界遗产为何诞生在景德镇？ 窑火夜夜明 申遗成功这天，位于景德镇陶阳里历史文化街区的徐家窑热得令人汗流浃背…"
