    "title": "台湾新北市发生4.8级地震",
    "link": "http://www.news.cn/20260726/1473d8d6b79243bb9adbe5c033e406d7/c.html",
    "pub_date": "2026-07-26 21:01:24",
    "author": "黄扬,褚萌萌",
    "description": "新华社台北7月26日电（记者黄扬、褚萌萌）据中国地震台网正式测定，7月26日20时36分在台湾新北市（北纬24.94度，东经121.82度）发生4.8级地震，震源深度95千米。 另据台湾地区气象部门测定，7月26日20时36分左右台湾北部地区发生5.6级地震。震中在新北市东南东方35.8公里，位于新北市双溪区。 地震发生时，记者在台北感受短暂的明显摇晃感。",
    "content": "新华社台北7月26日电（记者黄扬、褚萌萌）据中国地震台网正式测定，7月26日20时36分在台湾新北市（北纬24.94度，东经121.82度）发生4.8级地震，震源深度95千米。 另据台湾地区气象部门测定，7月26日20时36分左右台湾北部地区发生5.6级地震。震中在新北市东南东方35.8公里，位于新北市双溪区。 地震发生时，记者在台北感受短暂的明显摇晃感。"
