    "content": "26/07/2026 - 14:28 三名向中国竞争对手公司泄露大型有机发光二极管（OLED）显示器量产技术的韩企乐金显示（LG Display）前员工，在一审中分别被判处1年至5年不等有期徒刑。 据韩联社从法律界周日获悉，首尔中央地方法院刑事审判第34庭近日就尹某等三人向中国企业泄露显示器关键技术，涉嫌违反韩国《工业技术保护法》一案宣判，判处尹某有期徒刑5年、罚金4000万韩元（约合人民币18.5万元）；判处韩某有期徒刑2年、罚金1000万韩元；同时被起诉的朴某被判处1年有期徒刑，缓刑2年。 报导指，这三人均为韩…"
