    "content": "新华社达喀尔7月26日电（记者陈晨 齐琪）塞内加尔总统法耶25日在首都达喀尔宣布成立新政党“基拉伊—共和爱国者党”。当地舆论认为，这是法耶今年5月解除松科总理职务后，着手建立自身政治力量的重要一步。两名昔日政治盟友之间的裂痕由此进一步公开化。 新党筹建工作由塞内加尔前总理阿米娜塔·杜尔负责。她接受塞内加尔官媒《太阳报》采访时表示，法耶2025年11月要求她扩大和整合其支持力量，筹备工作严格按照总统要求推进，“9个月后，最终成立了这个政党”。 据媒体报道，法耶与松科曾是政治盟友。2024年总统选举前，松科因失去参选资…"
